ALTER TABLE public.membership_requests DROP CONSTRAINT membership_requests_amount_check;
ALTER TABLE public.membership_requests ADD CONSTRAINT membership_requests_amount_check CHECK (amount IN (80,100,349));
CREATE OR REPLACE FUNCTION public.has_paid_vehicle_chat(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND public.account_allowed(_user) AND (public.has_role(_user,'admin') OR EXISTS(SELECT 1 FROM public.membership_access a JOIN public.membership_requests r ON r.id=a.request_id AND r.user_id=a.user_id WHERE a.user_id=_user AND a.revoked_at IS NULL AND a.starts_at<=now() AND a.ends_at>now() AND r.amount IN (100,349) AND r.vehicle_plan_months=3 AND r.status='approved') OR EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='membership' AND payable_amount IN (100,349) AND plan_months=3 AND status='approved' AND received_at<=now() AND ends_at>now())) $$;
CREATE OR REPLACE FUNCTION public.has_paid_bell(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND public.account_allowed(_user) AND (public.has_role(_user,'admin') OR EXISTS(SELECT 1 FROM public.membership_access a JOIN public.membership_requests r ON r.id=a.request_id AND r.user_id=a.user_id WHERE a.user_id=_user AND a.revoked_at IS NULL AND a.starts_at<=now() AND a.ends_at>now() AND r.amount=349 AND r.vehicle_plan_months=3 AND r.status='approved') OR EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='membership' AND payable_amount=349 AND plan_months=3 AND status='approved' AND received_at<=now() AND ends_at>now())) $$;
CREATE OR REPLACE FUNCTION public.chat_only_viewer() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_paid_vehicle_chat(auth.uid()) AND NOT public.has_paid_bell(auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.contact_field_allowed(_owner uuid,_field text,_vehicle boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.has_role(auth.uid(),'admin'),false) OR (NOT public.chat_only_viewer() AND (NOT _vehicle OR public.has_paid_bell(auth.uid())) AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_owner AND public.account_allowed(p.id) AND p.public_bell_consent AND CASE _field WHEN 'name' THEN NOT coalesce(p.hide_name,true) WHEN 'phone' THEN NOT coalesce(p.hide_phone,true) WHEN 'photo' THEN NOT coalesce(p.hide_photo,true) ELSE false END)) $$;
GRANT EXECUTE ON FUNCTION public.has_paid_vehicle_chat(uuid), public.chat_only_viewer(), public.contact_field_allowed(uuid,text,boolean) TO anon,authenticated,service_role;
DO $$ DECLARE f text; sig text; BEGIN FOREACH sig IN ARRAY ARRAY['public.submit_membership_screenshot(integer,uuid,text,text)','public.register_membership_evidence(uuid,uuid,integer,text,uuid)'] LOOP f:=pg_get_functiondef(sig::regprocedure); IF position('_amount<>100' in f)=0 THEN RAISE EXCEPTION 'Unexpected payment definition: %',sig; END IF; f:=replace(f,'_amount<>100','_amount NOT IN (100,349)'); IF position('register_membership_evidence' in sig)>0 THEN f:=replace(f,'IF r.payer_id<>_payer OR r.user_id<>_user THEN','IF r.payer_id<>_payer OR r.user_id<>_user OR r.amount<>_amount THEN'); f:=replace(f,'INSERT INTO public.membership_requests(payer_id,user_id,amount,reference,message_id) VALUES(_payer,_user,_amount,_reference,_message)', 'INSERT INTO public.membership_requests(payer_id,user_id,amount,reference,message_id,vehicle_plan_months) VALUES(_payer,_user,_amount,_reference,_message,3)'); END IF; EXECUTE f; END LOOP; FOREACH sig IN ARRAY ARRAY['public.open_vehicle_chat(uuid)','public.open_vehicle_demand_chat(uuid)','public.open_anonymous_bell_chat(uuid,text)'] LOOP f:=pg_get_functiondef(sig::regprocedure); f:=replace(replace(f,'public.has_paid_bell(', 'public.has_paid_vehicle_chat('),'public.vehicle_contact_access(', 'public.has_paid_vehicle_chat('); EXECUTE f; END LOOP; END $$;
DO $$ DECLARE f text; BEGIN f:=pg_get_functiondef('public.can_post_chat(uuid,uuid)'::regprocedure); EXECUTE replace(f,'FUNCTION public.can_post_chat(', 'FUNCTION public.package_previous_can_post_chat('); END $$;
REVOKE ALL ON FUNCTION public.package_previous_can_post_chat(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND (public.package_previous_can_post_chat(_post,_other) OR ((public.has_paid_vehicle_chat(auth.uid()) OR public.has_paid_vehicle_chat(_other)) AND (EXISTS(SELECT 1 FROM public.post_chat_pairs c JOIN public.posts p ON p.id=c.post_id WHERE p.module='vehicle' AND (_post IS NULL OR c.post_id=_post) AND ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other))) OR (_post IS NULL AND EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) OR (_post IS NULL AND EXISTS(SELECT 1 FROM public.bell_board_chat_pairs c JOIN public.post_bell_interests i ON i.id=c.interest_id JOIN public.posts p ON p.id=i.post_id WHERE p.module='vehicle' AND ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other))))))) $$;
CREATE OR REPLACE FUNCTION public.my_prime99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('active',public.has_paid_vehicle_chat(auth.uid()),'chat_active',public.has_paid_vehicle_chat(auth.uid()),'bell_active',public.has_paid_bell(auth.uid()),'alerts_ready',public.paid_alert_ready(auth.uid()),'ends_at',(SELECT max(ends_at) FROM (SELECT a.ends_at FROM public.membership_access a JOIN public.membership_requests r ON r.id=a.request_id WHERE a.user_id=auth.uid() AND a.revoked_at IS NULL AND a.starts_at<=now() AND r.status='approved' AND r.amount IN(100,349) UNION ALL SELECT ends_at FROM public.prime99_payments WHERE user_id=auth.uid() AND payment_purpose='membership' AND status='approved' AND payable_amount IN(100,349)) a),'provisional',false,'amount',CASE WHEN public.has_paid_bell(auth.uid()) THEN 349 WHEN public.has_paid_vehicle_chat(auth.uid()) THEN 100 ELSE 0 END) $$;
CREATE OR REPLACE FUNCTION public.can_call_member(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND _other IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND (public.has_role(auth.uid(),'admin') OR public.has_role(_other,'admin') OR public.has_paid_bell(auth.uid())) AND (public.can_post_chat(NULL,_other) OR EXISTS(SELECT 1 FROM public.messages WHERE (sender_id=auth.uid() AND receiver_id=_other) OR (sender_id=_other AND receiver_id=auth.uid()))) $$;
DO $$ DECLARE f text; BEGIN f:=pg_get_functiondef('public.review_membership_evidence(uuid,boolean)'::regprocedure); f:=replace(f,''' నెలలు. గంట, సంభాషణ ఉపయోగించవచ్చు. పేరు, ఫోటో, నంబరు దాచబడతాయి.''', ''' నెలలు. ''||CASE WHEN r.amount=349 THEN ''చాట్, గంట, కాల్స్ మరియు అనుమతించిన వివరాలు ఉపయోగించవచ్చు.'' ELSE ''చాట్ మాత్రమే. గంట, పేరు, ఫోటో, నంబరు అందుబాటులో ఉండవు.'' END'); EXECUTE f; END $$;